Ext.define('BNK.view.HumanResource.hwm.HwmVctAply71MContainer_bakViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HwmVctAply71MContainer_bakViewController',

    config: {
        viewId: 'HwmVctAply71MContainer_bak'
    },

    addForm: function(detail) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            items = refs.vctItems; // 동적으로 생성된 form 들을 넣을 공간

        var strdtAndEdt = DateUtils.parseDate(vm.get('vct.aplVctStrdt')) + ' ~ ' + DateUtils.parseDate(vm.get('vct.aplVctEdt'));
        vm.set('vct.strdtAndEdt', strdtAndEdt); // 휴가기간

        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command   : vm.get('command'),
            viewModel : vm,
            aprHistId : vm.get('aprHistId'),
            edocCd    : 'HwmVctAply71',
            scope     : me
        });

        for(var i in detail){
            var item = null;
            item = Ext.create('HwmVctAply71MItem', { // alternateClassName // ExpNteAplyItems // HwmVctAply71MItem
                detail : detail[i] // HR_WRKD_VCT_APF
            });
            items.add(item);
        }

        // 첨부파일 영역 활성화
        if (vm.get('vct.atchFileId')) {
        //     refs.atchFile.setHidden(true);
            refs.downloadBtn.setDisabled(false);
        } else {
            refs.atchFileNm.setValue('첨부파일없음');
        //     refs.atchFile.setHidden(false);
            refs.downloadBtn.setDisabled(true);
        }
    },

    /* 첨부파일 다운로드 */
    onDownloadBtn: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            atchFileId = refs.atchFileId.getValue();

        if(atchFileId) {
            var downloadUrl = Property.BASE_URL + Property.DOWN_URL + atchFileId;
            var form = document.createElement("form");
            form.setAttribute("method", "get");
            form.setAttribute("action", downloadUrl);
            form.setAttribute("target", "_blank");

            document.body.appendChild(form);
            form.submit();
            document.body.removeChild(form);
        }
    },

    /* 화면초기화 */
    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();


    }

});